-- ux-c seams (M1): the one wave-1 migration (plan L7). Generated by
-- `drizzle-kit generate --name ux_c_seams` from tables.ts; the trigger at the
-- end is hand-added, since drizzle-kit does not model triggers.
--
-- 1. cellar_items gains the bottle's own dates (packaged_on, acquired_on,
--    drink_from, drink_until), its price (price_amount numeric(10,2) >= 0 and
--    price_currency char(3), set together or not at all) and a free-text
--    location of at most 80 characters. All nullable, so existing rows are
--    untouched; drink_from <= drink_until only when both are set.
-- 2. check_ins.recipe_id: a check-in of a drink made from a recipe. It counts
--    as the target in check_ins_one_item, which widens to exactly one of the
--    six item columns or recipe_id, as want_to_try_one_target does. Indexed for
--    the recipe's own log. ON DELETE SET NULL as the contract states: note that
--    nulling the only target of a recipe check-in fails check_ins_one_item, so
--    a recipe with check-ins cannot be hard-deleted until its delete path
--    decides what those check-ins become.
-- 3. item_brew_prefs: a person's own brew settings for one item, mirroring
--    want_to_try (RESTRICT foreign keys, one UNIQUE (user_id, <type>_id) per
--    column, exactly one target), with a positive-value CHECK on each of the
--    four nullable settings and water_temp_c in 1..100. updated_at is stamped
--    by the shared trigger function, like every table not named in
--    updated-at-triggers.test.ts's WRITER_STAMPED.
CREATE TABLE "item_brew_prefs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),
	"user_id" uuid NOT NULL,
	"beer_id" uuid,
	"wine_id" uuid,
	"spirit_id" uuid,
	"coffee_id" uuid,
	"sake_id" uuid,
	"tea_id" uuid,
	"water_temp_c" smallint,
	"steep_seconds" integer,
	"dose_grams" real,
	"water_ml" real,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "item_brew_prefs_user_id_beer_id_key" UNIQUE("user_id","beer_id"),
	CONSTRAINT "item_brew_prefs_user_id_coffee_id_key" UNIQUE("user_id","coffee_id"),
	CONSTRAINT "item_brew_prefs_user_id_sake_id_key" UNIQUE("user_id","sake_id"),
	CONSTRAINT "item_brew_prefs_user_id_spirit_id_key" UNIQUE("user_id","spirit_id"),
	CONSTRAINT "item_brew_prefs_user_id_tea_id_key" UNIQUE("user_id","tea_id"),
	CONSTRAINT "item_brew_prefs_user_id_wine_id_key" UNIQUE("user_id","wine_id"),
	CONSTRAINT "item_brew_prefs_one_target" CHECK ((num_nonnulls(beer_id, wine_id, spirit_id, coffee_id, sake_id, tea_id) = 1)),
	CONSTRAINT "item_brew_prefs_water_temp_c_range" CHECK (((water_temp_c IS NULL) OR ((water_temp_c >= 1) AND (water_temp_c <= 100)))),
	CONSTRAINT "item_brew_prefs_steep_seconds_positive" CHECK (((steep_seconds IS NULL) OR (steep_seconds > 0))),
	CONSTRAINT "item_brew_prefs_dose_grams_positive" CHECK (((dose_grams IS NULL) OR (dose_grams > (0)::double precision))),
	CONSTRAINT "item_brew_prefs_water_ml_positive" CHECK (((water_ml IS NULL) OR (water_ml > (0)::double precision)))
);
